    "key_info_rows": [
      {
        "Key": "Visa Requirement",
        "Value": "US citizens must obtain a valid visa to enter Vietnam, even for short tourist visits. There is no visa exemption for US citizens."
      },
      {
        "Key": "E-Visa Option",
        "Value": "For tourism, the Vietnamese e-visa is widely available and suitable for stays up to 90 days, including single and multiple entries. This covers visits shorter than 30 days."
      },
      {
        "Key": "Validity",
        "Value": "An e-visa typically allows a stay of up to 90 days from the specified entry date. Ensure your intended stay falls within this period."
      },
      {
        "Key": "Required Documents (for E-visa)",
        "Value": "A scanned copy of your passport bio-page (must be valid for at least six months beyond your intended entry date).\nA recent passport-style digital photo (plain white background, no glasses, no head covering).\nDetails of your planned entry and exit dates.\nProposed entry and exit checkpoints (airports, land borders, seaports)."
      }
    ],
    "application_notes_rows": [
      {
        "Key": "Application Portal",
        "Value": "Applications for the e-visa are submitted online through the official Vietnam Immigration Department website."
      },
      {
        "Key": "Processing Time",
        "Value": "Standard processing typically takes 3-5 working days, but it's advisable to apply at least 1-2 weeks before your travel date to account for any unforeseen delays."
      },
      {
        "Key": "Passport Validity",
        "Value": "Your passport must be valid for at least six months beyond your planned date of entry into Vietnam."
      },
      {
        "Key": "Print E-visa",
        "Value": "After approval, you must print out your e-visa to present upon arrival. Digital copies on a phone are generally not sufficient."
      },
      {
        "Key": "Entry/Exit Points",
        "Value": "Ensure the entry and exit points chosen during your e-visa application match your actual travel plans."
      }
    ]
  },
